using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace V15Voice {public partial class MainForm {
 ComboBox voiceMode=new ComboBox(),secondVoice=new ComboBox();Label secondVoiceNote=new Label();FlowLayoutPanel speakerTools;bool speakerLoading;
 bool TwoSpeakers{get{return voiceMode.SelectedIndex==1;}}
 string SecondKey(){var item=secondVoice.SelectedItem as VoiceItem;return item==null?"":item.Key;}
 void FillSecondVoice(string keep=null){keep=keep??SecondKey();speakerLoading=true;try{secondVoice.Items.Clear();foreach(var p in catalog.All)secondVoice.Items.Add(new VoiceItem{Key=p.Key,Name=(p.Recommended?"★ ":"")+p.Name+" · "+p.Kind+" · "+p.MainStyle});secondVoice.SelectedIndex=-1;for(int i=0;i<secondVoice.Items.Count;i++)if(((VoiceItem)secondVoice.Items[i]).Key==keep){secondVoice.SelectedIndex=i;break;}}finally{speakerLoading=false;}RefreshSecondVoice();}
 void RefreshSecondVoice(){if(speakerLoading)return;var key=SecondKey();var p=catalog.All.FirstOrDefault(v=>v.Key==key);secondVoiceNote.Text=p==null?"Chọn giọng B trước khi tạo. Dùng chung với hàng đợi.":"B · "+p.MainStyle+" · "+p.Gender+". "+p.Description;}
 void BuildSpeakerControls(){
  voiceMode.DropDownStyle=ComboBoxStyle.DropDownList;voiceMode.Items.AddRange(new object[]{"1 giọng","2 giọng · A / B"});voiceMode.SelectedIndex=0;voiceMode.AccessibleName="Chế độ một hoặc hai giọng";
  secondVoice.DropDownStyle=ComboBoxStyle.DropDownList;secondVoice.IntegralHeight=false;secondVoice.DropDownHeight=380;secondVoice.DropDownWidth=760;secondVoice.AccessibleName="Giọng B";FillSecondVoice();
  secondVoiceNote.AutoSize=true;secondVoiceNote.MaximumSize=new Size(350,0);secondVoiceNote.ForeColor=muted;
  grid.Columns.Add(new DataGridViewComboBoxColumn{Name="speaker",HeaderText="Giọng",DataSource=new[]{"A","B"},Width=70,DisplayIndex=1,FlatStyle=FlatStyle.Flat});grid.DataError+=(s,e)=>{e.ThrowException=false;status.Text="Cột Giọng chỉ nhận A hoặc B.";};
  grid.CurrentCellDirtyStateChanged+=(s,e)=>{if(grid.IsCurrentCellDirty&&grid.CurrentCell!=null&&grid.CurrentCell.OwningColumn.Name=="speaker")grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};
  grid.CellValueChanged+=(s,e)=>{if(!anchorGridLoading&&e.RowIndex>=0&&e.ColumnIndex==grid.Columns["speaker"].Index){try{ReadGrid();}catch(Exception x){status.Text=x.Message;}}};
  speakerTools=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};
  speakerTools.Controls.Add(Btn("Xen kẽ A–B",(s,e)=>AssignSpeakers("alternate")));speakerTools.Controls.Add(Btn("Gán A",(s,e)=>AssignSpeakers("A")));speakerTools.Controls.Add(Btn("Gán B",(s,e)=>AssignSpeakers("B")));speakerTools.Controls.Add(Btn("Lưu kịch bản A/B…",(s,e)=>SaveSpeakerScript()));
  var left=(TableLayoutPanel)grid.Parent;left.RowCount=5;left.RowStyles.Insert(2,new RowStyle(SizeType.Absolute,45));left.SetRow(grid,3);left.SetRow(wavePanel,4);left.Controls.Add(speakerTools,0,2);
  voiceMode.SelectedIndexChanged+=(s,e)=>{RefreshSpeakerMode();if(!restoring&&!busy){readingLive=false;targetCalibration=null;SaveSession();}};
  secondVoice.SelectedIndexChanged+=(s,e)=>{RefreshSecondVoice();if(!restoring&&!busy){readingLive=false;targetCalibration=null;UpdateShared();SaveSession();}};RefreshSpeakerMode();
 }
 void RefreshSpeakerMode(){if(grid.Columns.Contains("speaker"))grid.Columns["speaker"].Visible=TwoSpeakers;if(speakerTools!=null){speakerTools.Visible=TwoSpeakers;var left=speakerTools.Parent as TableLayoutPanel;if(left!=null)left.RowStyles[2].Height=TwoSpeakers?45:0;}secondVoice.Enabled=TwoSpeakers&&!busy;if(studioSidebar!=null)ResizeStudioSidebar();if(batchInfo!=null)UpdateShared();}
 void DetectSpeakers(IEnumerable<Cue> input){if(input.Any(c=>!String.IsNullOrEmpty(c.Speaker)))voiceMode.SelectedIndex=1;}
 void AssignSpeakers(string who){if(busy)return;try{ReadGrid();if(cues.Count==0)return;TwoVoiceSelected();var rows=grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.Index).OrderBy(i=>i).ToList();if(who=="alternate")rows=Enumerable.Range(0,cues.Count).ToList();if(rows.Any(i=>!String.IsNullOrEmpty(cues[i].VoiceLock)))throw new Exception("Mở khóa các đoạn TXT được chọn trước khi đổi giọng.");anchorGridLoading=true;try{foreach(int i in rows){grid.Rows[i].Cells["speaker"].Value=who=="alternate"?(i%2==0?"A":"B"):who;}}finally{anchorGridLoading=false;}ReadGrid();status.Text=who=="alternate"?"Đã gán xen kẽ A/B; có thể sửa riêng từng câu.":"Đã gán giọng "+who+" cho câu được chọn.";}catch(Exception x){Error(x);}}
 void TwoVoiceSelected(){voiceMode.SelectedIndex=1;}
 string VoiceDescription(VoiceProfile p){string hash=!String.IsNullOrEmpty(p.ReferencePath)&&File.Exists(p.ReferencePath)?" · mẫu "+Path.GetFileName(p.ReferencePath)+" · SHA256 "+StateFiles.Hash(p.ReferencePath):"";return p.Name+" · mã "+p.Key+" · "+p.Kind+" / "+p.ModelFolder+" / speaker "+p.Speaker+" · phong cách "+p.Styles+" · "+p.Description+" · nguồn "+p.Source+hash;}
 void AddSpeakerOptions(RenderOptions o){o.TwoVoices=TwoSpeakers;o.VoiceAKey=Key();o.VoiceAInfo=VoiceDescription(catalog.Get(Key()));o.VoiceBKey=SecondKey();var p=catalog.All.FirstOrDefault(v=>v.Key==o.VoiceBKey);o.VoiceBInfo=p==null?"chưa chọn":VoiceDescription(p);}
 KokoroEngine RunEngine(List<Cue> input){if(!TwoSpeakers)return NewEngine();var p=catalog.All.FirstOrDefault(v=>v.Key==SecondKey());if(p==null)throw new Exception("Chọn giọng B ở mục Giọng đọc trước khi tạo hai giọng.");var a=NewEngine();try{return new TwoVoiceEngine(a,EngineFor(p),Key(),p.Key,input);}catch{a.Dispose();throw;}}
 KokoroEngine CueEngine(Cue c){if(TwoSpeakers&&SpeakerScript.Role(c)=="B"){var p=catalog.All.FirstOrDefault(v=>v.Key==SecondKey());if(p==null)throw new Exception("Chưa chọn giọng B.");return EngineFor(p);}if(!TwoSpeakers&&SpeakerScript.Role(c)=="B")throw new Exception("Bật 2 giọng để đọc câu B.");return NewEngine();}
 void SaveSpeakerScript(){try{ReadGrid();using(var d=new SaveFileDialog{Filter=proseInput?"TXT có nhãn|*.txt":"SRT có nhãn A/B|*.srt",FileName=String.IsNullOrEmpty(sourcePath)?"kich_ban_2_giong":Path.GetFileNameWithoutExtension(sourcePath)+"_2_giong",OverwritePrompt=true}){if(d.ShowDialog()!=DialogResult.OK)return;if(!String.IsNullOrEmpty(sourcePath)&&String.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(sourcePath),StringComparison.OrdinalIgnoreCase))throw new Exception("Chọn tên mới để giữ nguyên file nguồn.");var copy=VoiceRenderReport.Snapshot(cues);foreach(var c in copy)c.Speaker=SpeakerScript.Role(c);File.WriteAllText(d.FileName,proseInput?String.Join("\r\n",copy.Select(SpeakerScript.Tagged)):Scripts.ToSrt(copy),new System.Text.UTF8Encoding(false));status.Text="Đã lưu kịch bản A/B: "+d.FileName;}}catch(Exception x){Error(x);}}
}}
